content.arguments:
{"content": """"SQLite-backed word database.

The shipped database is generated from ``data/words.json``.  The schema is
deliberately small and transparent: one row per secret word, with the fields
needed to build a clue and a semantic vector.
"""

from __future__ import annotations

import json
import os
import random
import sqlite3
import tempfile
from dataclasses import dataclass
from pathlib import Path
from typing import Iterable, Sequence

PACKAGE_DIR = Path(__file__).resolve().parent
DEFAULT_DB_PATH = PACKAGE_DIR / "data" / "words.db"
DEFAULT_SEED_PATH = PACKAGE_DIR / "data" / "words.json"

SCHEMA = """
PRAGMA user_version = 1;

CREATE TABLE words (
    id             INTEGER PRIMARY KEY,
    word           TEXT NOT NULL UNIQUE COLLATE NOCASE,
    pos            TEXT NOT NULL,
    definition     TEXT NOT NULL,
    category       TEXT NOT NULL,
    synonyms       TEXT NOT NULL DEFAULT '',
    related        TEXT NOT NULL DEFAULT '',
    example        TEXT NOT NULL DEFAULT '',
    difficulty     TEXT NOT NULL,
    frequency_rank INTEGER
);

CREATE INDEX idx_words_category ON words(category);
CREATE INDEX idx_words_difficulty ON words(difficulty);

CREATE TABLE metadata (
    key   TEXT PRIMARY KEY,
    value TEXT NOT NULL
);
"""


def split_list(value: str | Sequence[str] | None) -> tuple[str, ...]:
    """Return a clean tuple from a comma-separated string or a sequence."""
    if value is None:
        return ()
    if isinstance(value, str):
        parts = value.split(",")
    else:
        parts = list(value)
    result: list[str] = []
    seen: set[str] = set()
    for part in parts:
        item = " ".join(str(part).strip().split())
        key = item.casefold()
        if item and key not in seen:
            seen.add(key)
            result.append(item)
    return tuple(result)


@dataclass(frozen=True, slots=True)
class WordEntry:
    """One secret word and the data used to describe and score it."""

    id: int
    word: str
    pos: str
    definition: str
    category: str
    synonyms: tuple[str, ...] = ()
    related: tuple[str, ...] = ()
    example: str = ""
    difficulty: str = "medium"
    frequency_rank: int | None = None

    @property
    def letter_count(self) -> int:
        return sum(1 for ch in self.word if ch.isalpha())

    @property
    def display_pos(self) -> str:
        return {
            "n": "noun",
            "v": "verb",
            "a": "adjective",
            "s": "adjective",
            "r": "adverb",
        }.get(self.pos, self.pos)

    @property
    def synonyms_text(self) -> str:
        return ", ".join(self.synonyms)


def _load_seed(seed_path: Path) -> tuple[list[dict], dict]:
    with seed_path.open("r", encoding="utf-8") as handle:
        raw = json.load(handle)
    if isinstance(raw, dict):
        words = raw.get("words", [])
        metadata = dict(raw.get("metadata", {}))
    else:
        words, metadata = raw, {}
    if not isinstance(words, list) or not words:
        raise ValueError(f"No words found in seed file: {seed_path}")
    return words, metadata


def build_database(seed_path: str | Path, db_path: str | Path) -> Path:
    """Build (or rebuild) the SQLite database from a JSON seed file.

    The database is written atomically, so an interrupted rebuild cannot leave
    a half-written game database behind.
    """

    seed_path = Path(seed_path)
    db_path = Path(db_path)
    words, metadata = _load_seed(seed_path)
    db_path.parent.mkdir(parents=True, exist_ok=True)

    fd, temp_name = tempfile.mkstemp(
        prefix=db_path.name + ".", suffix=".tmp", dir=str(db_path.parent)
    )
    os.close(fd)
    temp_path = Path(temp_name)
    try:
        connection = sqlite3.connect(temp_path)
        try:
            connection.executescript(SCHEMA)
            rows = []
            for item in words:
                word = " ".join(str(item["word"]).strip().split())
                rows.append(
                    (
                        word,
                        str(item.get("pos", "n")).strip(),
                        " ".join(str(item["definition"]).strip().split()),
                        " ".join(str(item["category"]).strip().split()),
                        ", ".join(split_list(item.get("synonyms"))),
                        ", ".join(split_list(item.get("related"))),
                        " ".join(str(item.get("example", "")).strip().split()),
                        str(item.get("difficulty", "medium")).strip(),
                        item.get("frequency_rank"),
                    )
                )
            connection.executemany(
                """
                INSERT INTO words
                    (word, pos, definition, category, synonyms, related,
                     example, difficulty, frequency_rank)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                rows,
            )
            meta = {
                "word_count": str(len(rows)),
                "source": "WordNet 3.0 + google-10000-english",
                "license": "WordNet 3.0 license (see WORDNET_LICENSE.txt)",
            }
            meta.update({str(k): str(v) for k, v in metadata.items()})
            connection.executemany(
                "INSERT OR REPLACE INTO metadata(key, value) VALUES (?, ?)",
                sorted(meta.items()),
            )
            connection.commit()
        finally:
            connection.close()
        os.replace(temp_path, db_path)
    except BaseException:
        temp_path.unlink(missing_ok=True)
        raise
    return db_path


def _normalise_term(term: str) -> str:
    text = " ".join(str(term).strip().casefold().replace("-", " ").split())
    return text


def _singular_candidates(term: str) -> Iterable[str]:
    if len(term) < 4 or " " in term:
        return ()
    candidates: list[str] = []
    if term.endswith("ies"):
        candidates.append(term[:-3] + "y")
    if term.endswith("ves"):
        candidates.append(term[:-3] + "f")
        candidates.append(term[:-3] + "fe")
    if term.endswith("es"):
        candidates.append(term[:-2])
        candidates.append(term[:-1])
    if term.endswith("s") and not term.endswith("ss"):
        candidates.append(term[:-1])
    if term.endswith("ing") and len(term) > 5:
        candidates.append(term[:-3])
        candidates.append(term[:-3] + "e")
    if term.endswith("ed") and len(term) > 4:
        candidates.append(term[:-2])
        candidates.append(term[:-1])
    return tuple(dict.fromkeys(candidates))


class WordRepository:
    """Read-only access to the word database, plus alias lookup."""

    def __init__(self, db_path: str | Path | None = None) -> None:
        self.db_path = Path(db_path) if db_path else DEFAULT_DB_PATH
        if not self.db_path.exists():
            build_database(DEFAULT_SEED_PATH, self.db_path)
        self._connection = sqlite3.connect(str(self.db_path))
        self._connection.row_factory = sqlite3.Row
        self._entries = self._load_entries()
        if not self._entries:
            raise RuntimeError(f"Word database is empty: {self.db_path}")

        self._by_word: dict[str, WordEntry] = {}
        self._aliases: dict[str, list[WordEntry]] = {}
        for entry in self._entries:
            self._by_word[entry.word.casefold()] = entry
            self._aliases.setdefault(entry.word.casefold(), []).append(entry)
            for synonym in entry.synonyms:
                self._aliases.setdefault(synonym.casefold(), []).append(entry)

    def _load_entries(self) -> tuple[WordEntry, ...]:
        rows = self._connection.execute(
            """
            SELECT id, word, pos, definition, category, synonyms, related,
                   example, difficulty, frequency_rank
            FROM words
            ORDER BY id
            """
        ).fetchall()
        return tuple(
            WordEntry(
                id=int(row["id"]),
                word=str(row["word"]),
                pos=str(row["pos"]),
                definition=str(row["definition"]),
                category=str(row["category"]),
                synonyms=split_list(row["synonyms"]),
                related=split_list(row["related"]),
                example=str(row["example"]),
                difficulty=str(row["difficulty"]),
                frequency_rank=(
                    int(row["frequency_rank"])
                    if row["frequency_rank"] is not None
                    else None
                ),
            )
            for row in rows
        )

    @property
    def entries(self) -> tuple[WordEntry, ...]:
        return self._entries

    def __len__(self) -> int:
        return len(self._entries)

    def __enter__(self) -> "WordRepository":
        return self

    def __exit__(self, *exc_info: object) -> None:
        self.close()

    def close(self) -> None:
        self._connection.close()

    def get(self, term: str) -> WordEntry | None:
        """Look up an exact word (case-insensitive), then a plural form."""
        key = _normalise_term(term)
        if not key:
            return None
        entry = self._by_word.get(key)
        if entry is not None:
            return entry
        for candidate in _singular_candidates(key):
            entry = self._by_word.get(candidate)
            if entry is not None:
                return entry
        return None

    def candidates(self, term: str) -> tuple[WordEntry, ...]:
        """Return every entry whose word or synonym matches ``term``."""
        key = _normalise_term(term)
        if not key:
            return ()
        exact = self._by_word.get(key)
        if exact is not None:
            return (exact,)
        found = self._aliases.get(key, ())
        if found:
            # Preserve order but drop duplicates.
            return tuple(dict.fromkeys(found))
        for candidate in _singular_candidates(key):
            exact = self._by_word.get(candidate)
            if exact is not None:
                return (exact,)
            found = self._aliases.get(candidate, ())
            if found:
                return tuple(dict.fromkeys(found))
        return ()

    def suggest(self, term: str, limit: int = 3) -> tuple[str, ...]:
        """Suggest close spellings from the database vocabulary."""
        import difflib

        key = _normalise_term(term)
        if not key:
            return ()
        choices = sorted(self._by_word)
        return tuple(difflib.get_close_matches(key, choices, n=limit, cutoff=0.72))

    def categories(self) -> tuple[str, ...]:
        return tuple(
            row[0]
            for row in self._connection.execute(
                "SELECT DISTINCT category FROM words ORDER BY category"
            )
        )

    def difficulties(self) -> tuple[str, ...]:
        order = {"easy": 0, "medium": 1, "hard": 2}
        values = [
            row[0]
            for row in self._connection.execute(
                "SELECT DISTINCT difficulty FROM words"
            )
        ]
        return tuple(sorted(values, key=lambda value: order.get(value, 99)))

    def sample(
        self,
        rng: random.Random,
        category: str | None = None,
        difficulty: str | None = None,
    ) -> WordEntry:
        pool = self._entries
        if category:
            wanted = category.casefold()
            pool = tuple(e for e in pool if e.category.casefold() == wanted)
        if difficulty:
            wanted = difficulty.casefold()
            pool = tuple(e for e in pool if e.difficulty.casefold() == wanted)
        if not pool:
            filters = []
            if category:
                filters.append(f"category={category!r}")
            if difficulty:
                filters.append(f"difficulty={difficulty!r}")
            raise LookupError("No words match " + " and ".join(filters))
        return rng.choice(pool)
