        candidates.append(term[:-1])
    if term.endswith("ing") and len(term) > 5:
        candidates.append(term[:-3])
        candidates.append(term[:-3] + "e")
    if term.endswith("ed") and len(term) > 4:
        candidates.append(term[:-2])
