from typing import Iterable, Sequence

PACKAGE_DIR = Path(__file__).resolve().parent
DEFAULT_DB_PATH = PACKAGE_DIR / "data" / "words.db"
DEFAULT_SEED_PATH = PACKAGE_DIR / "data" / "words.json"

SCHEMA = """
PRAGMA user_version = 1;

CREATE TABLE words (
    id             INTEGER PRIMARY KEY,
    word           TEXT NOT NULL UNIQUE COLLATE NOCASE,
    pos            TEXT NOT NULL,
    definition     TEXT NOT NULL,
    category       TEXT NOT NULL,
    synonyms       TEXT NOT NULL DEFAULT '',
    related        TEXT NOT NULL DEFAULT '',
    example        TEXT NOT NULL DEFAULT '',
    difficulty     TEXT NOT NULL,
    frequency_rank INTEGER
);

CREATE INDEX idx_words_category ON words(category);
CREATE INDEX idx_words_difficulty ON words(difficulty);

CREATE TABLE metadata (
    key   TEXT PRIMARY KEY,
    value TEXT NOT NULL
);
"""


def split_list(value: str | Sequence[str] | None) -> tuple[str, ...]:
    """Return a clean tuple from a comma-separated string or a sequence."""
    if value is None:
        return ()
    if isinstance(value, str):
        parts = value.split(",")
    else:
        parts = list(value)
    result: list[str] = []
    seen: set[str] = set()
    for part in parts:
        item = " ".join(str(part).strip().split())
        key = item.casefold()
        if item and key not in seen:
            seen.add(key)
            result.append(item)
    return tuple(result)


@dataclass(frozen=True, slots=True)
class WordEntry:
    """One secret word and the data used to describe and score it."""

    id: int
    word: str
    pos: str
    definition: str
    category: str
    synonyms: tuple[str, ...] = ()
    related: tuple[str, ...] = ()
    example: str = ""
    difficulty: str = "medium"
    frequency_rank: int | None = None

    @property
    def letter_count(self) -> int:
        return sum(1 for ch in self.word if ch.isalpha())

    @property
    def display_pos(self) -> str:
        return {
            "n": "noun",
            "v": "verb",
            "a": "adjective",
            "s": "adjective",
            "r": "adverb",
        }.get(self.pos, self.pos)

    @property
    def synonyms_text(self) -> str:
        return ", ".join(self.synonyms)


def _load_seed(seed_path: Path) -> tuple[list[dict], dict]:
    with seed_path.open("r", encoding="utf-8") as handle:
        raw = json.load(handle)
    if isinstance(raw, dict):
        words = raw.get("words", [])
        metadata = dict(raw.get("metadata", {}))
    else:
        words, metadata = raw, {}
    if not isinstance(words, list) or not words:
        raise ValueError(f"No words found in seed file: {seed_path}")
    return words, metadata


def build_database(seed_path: str | Path, db_path: str | Path) -> Path:
    """Build (or rebuild) the SQLite database from a JSON seed file.

    The database is written atomically, so an interrupted rebuild cannot leave
    a half-written game database behind.
    """

    seed_path = Path(seed_path)
    db_path = Path(db_path)
    words, metadata = _load_seed(seed_path)
    db_path.parent.mkdir(parents=True, exist_ok=True)

    fd, temp_name = tempfile.mkstemp(
        prefix=db_path.name + ".", suffix=".tmp", dir=str(db_path.parent)
    )
    os.close(fd)
    temp_path = Path(temp_name)
    try:
        connection = sqlite3.connect(temp_path)
        try:
            connection.executescript(SCHEMA)
            rows = []
            for item in words:
                word = " ".join(str(item["word"]).strip().split())
                rows.append(
                    (
                        word,
                        str(item.get("pos", "n")).strip(),
                        " ".join(str(item["definition"]).strip().split()),
                        " ".join(str(item["category"]).strip().split()),
                        ", ".join(split_list(item.get("synonyms"))),
                        ", ".join(split_list(item.get("related"))),
                        " ".join(str(item.get("example", "")).strip().split()),
                        str(item.get("difficulty", "medium")).strip(),
                        item.get("frequency_rank"),
                    )
                )
            connection.executemany(
                """
                INSERT INTO words
                    (word, pos, definition, category, synonyms, related,
                     example, difficulty, frequency_rank)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                rows,
            )
            meta = {
                "word_count": str(len(rows)),
                "source": "WordNet 3.0 + google-10000-english",
                "license": "WordNet 3.0 license (see WORDNET_LICENSE.txt)",
            }
            meta.update({str(k): str(v) for k, v in metadata.items()})
            connection.executemany(
                "INSERT OR REPLACE INTO metadata(key, value) VALUES (?, ?)",
                sorted(meta.items()),
            )
            connection.commit()
        finally:
            connection.close()
        os.replace(temp_path, db_path)
    except BaseException:
        temp_path.unlink(missing_ok=True)
        raise
    return db_path


