{"content": """"Semantic similarity scoring for word guesses.

Each word is represented as a sparse TF-IDF vector built from its definition,
category, synonyms, and related WordNet concepts.  Comparing two vectors with
cosine similarity gives a dependency-free, deterministic semantic score.
"""

from __future__ import annotations

import math
import re
from collections import Counter
from dataclasses import dataclass
from typing import Iterable, Mapping

from .database import WordEntry, WordRepository, _normalise_term

_TOKEN_RE = re.compile(r"[a-z]+(?:'[a-z]+)?")

STOP_WORDS = frozenset(
    """
    a about above after again against all almost along also although always am
    among an and another any anybody anyone anything are area around as at be
    because been before being below between both but by can cannot could did do
    does doing done down during each either else enough especially etc even ever
    every everyone everything except far few first for from further get gets
    getting give given go goes going good got had has have having he her here
    hers herself him himself his how however i if in into is it its itself just
    keep know last least less let like likely long made make makes making many
    may me might more most mostly much must my myself near need never new next
    no nor not now of off often on once one only or other others our ours
    ourselves out over own per perhaps put quite rather really same say says
    see seem seems several shall she should show side since so some someone
    something sometimes still such sure take than that the their theirs them
    themselves then there these they thing things think this those though
    through thus time to too toward two under until up upon us use used using
    very via want was way we well were what when where whether which while who
    whom whose why will with within without would yes yet you your yours
    yourself yourselves
    """.split()
)


def tokenize(text: str) -> list[str]:
    """Tokenize lowercase English text and apply a light plural/suffix fold."""
    tokens: list[str] = []
    for raw in _TOKEN_RE.findall(text.casefold()):
        if raw in STOP_WORDS or len(raw) < 2:
            continue
        tokens.append(raw)
        folded = _stem(raw)
        if folded != raw and folded not in STOP_WORDS and len(folded) >= 2:
            tokens.append(folded)
    return tokens


def _stem(word: str) -> str:
    """A deliberately small stemmer, tuned for dictionary definitions.

    It is not a full Porter stemmer.  It handles the common inflections that
    matter for short glosses (plural nouns, -ing, -ed) without pulling in a
    third-party NLP dependency.
    """
    if len(word) <= 3:
        return word
    if word.endswith("ies") and len(word) > 4:
        return word[:-3] + "y"
    if word.endswith(("sses", "shes", "ches", "xes", "zes")):
        return word[:-2]
    if word.endswith("s") and not word.endswith(("ss", "us", "is")):
        return word[:-1]
    if word.endswith("ing") and len(word) > 5:
        base = word[:-3]
        if len(base) >= 2 and base[-1] == base[-2] and base[-1] not in "aeiou":
            base = base[:-1]
        return base
    if word.endswith("ed") and len(word) > 4:
        base = word[:-2]
        if len(base) >= 2 and base[-1] == base[-2] and base[-1] not in "aeiou":
            base = base[:-1]
        return base
    return word


@dataclass(frozen=True, slots=True)
class ScoreResult:
    """The outcome of comparing one guess with the secret word."""

    cosine: float
    points: float
    known: bool
    correct: bool
    matched_word: str | None = None


class SemanticScorer:
    """Build and compare TF-IDF semantic vectors for database words."""

    def __init__(self, entries: Iterable[WordEntry]) -> None:
        self._entries = tuple(entries)
        if not self._entries:
            raise ValueError("SemanticScorer needs at least one word")
        documents = [self._document(entry) for entry in self._entries]
        document_frequency: Counter[str] = Counter()
        for document in documents:
            document_frequency.update(set(document))

        size = len(documents)
        self._idf: dict[str, float] = {
            token: math.log((1.0 + size) / (1.0 + frequency)) + 1.0
            for token, frequency in document_frequency.items()
        }
        self._vectors: list[dict[str, float]] = [
            self._vector(document) for document in documents
        ]
        self._vector_by_id: dict[int, dict[str, float]] = {
            entry.id: vector for entry, vector in zip(self._entries, self._vectors)
        }

    @staticmethod
    def _document(entry: WordEntry) -> list[str]:
        """Turn a word entry into a weighted bag of semantic tokens."""
        parts = [
            entry.category,
            entry.category,
            entry.category,
            entry.definition,
            entry.definition,
            " ".join(entry.synonyms),
            " ".join(entry.synonyms),
            " ".join(entry.related),
        ]
        return tokenize(" ".join(parts))

    def _vector(self, document: Iterable[str]) -> dict[str, float]:
        counts = Counter(document)
        vector = {
            token: (1.0 + math.log(count)) * self._idf.get(token, 1.0)
            for token, count in counts.items()
        }
        norm = math.sqrt(sum(value * value for value in vector.values()))
        if norm == 0.0:
            return {}
        return {token: value / norm for token, value in vector.items()}

    @staticmethod
    def _cosine(
        left: Mapping[str, float], right: Mapping[str, float]
    ) -> float:
        if len(left) > len(right):
            left, right = right, left
        dot = sum(value * right.get(token, 0.0) for token, value in left.items())
        if dot <= 0.0:
            return 0.0
        return max(0.0, min(1.0, dot))

    def vector_for(self, entry: WordEntry) -> Mapping[str, float]:
        return self._vector_by_id.get(entry.id, {})

    def score(
        self,
        target: WordEntry,
        guess: str,
        repository: WordRepository,
    ) -> ScoreResult:
        """Score ``guess`` against ``target`` on a 0-100 scale."""
        key = _normalise_term(guess)
        if not key:
            return ScoreResult(0.0, 0.0, known=False, correct=False)

        target_synonyms = {synonym.casefold() for synonym in target.synonyms}
        if key == target.word.casefold() or key in target_synonyms:
            return ScoreResult(1.0, 100.0, known=True, correct=True,
                               matched_word=target.word)

        candidates = repository.candidates(guess)
        if not candidates:
            return ScoreResult(0.0, 0.0, known=False, correct=False)

        target_vector = self.vector_for(target)
        best_entry: WordEntry | None = None
        best_cosine = 0.0
        for candidate in candidates:
            similarity = self._cosine(target_vector, self.vector_for(candidate))
            if best_entry is None or similarity > best_cosine:
                best_entry, best_cosine = candidate, similarity

        # A generated entry can be nearly identical to another entry (for
        # example, two senses with the same gloss).  Only an exact answer or a
        # listed synonym earns a perfect 100.
        points = round(best_cosine * 100.0, 1)
        if points >= 100.0:
            points = 99.9
        return ScoreResult(
            cosine=best_cosine,
            points=points,
            known=True,
            correct=False,
            matched_word=best_entry.word if best_entry else None,
        )

    def similarity(self, left: WordEntry, right: WordEntry) -> float:
        """Return the cosine similarity between two database entries."""
        return self._cosine(self.vector_for(left), self.vector_for(right))

    def nearest(
        self, entry: WordEntry, limit: int = 5
    ) -> tuple[tuple[WordEntry, float], ...]:
        """Return the most semantically similar database entries."""
        scored = [
            (other, self.similarity(entry, other))
            for other in self._entries
            if other.id != entry.id
        ]
