class SemanticScorer:
    """Build and compare TF-IDF semantic vectors for database words."""

    def __init__(self, entries: Iterable[WordEntry]) -> None:
        self._entries = tuple(entries)
        if not self._entries:
            raise ValueError("SemanticScorer needs at least one word")
        documents = [self._document(entry) for entry in self._entries]
