        for document in documents:
            document_frequency.update(set(document))

        size = len(documents)
        self._idf: dict[str, float] = {
            token: math.log((1.0 + size) / (1.0 + frequency)) + 1.0
            for token, frequency in document_frequency.items()
        }
        self._vectors: list[dict[str, float]] = [
            self._vector(document) for document in documents
        ]
        self._vector_by_id: dict[int, dict[str, float]] = {
            entry.id: vector for entry, vector in zip(self._entries, self._vectors)
        }

    @staticmethod
    def _document(entry: WordEntry) -> list[str]:
        """Turn a word entry into a weighted bag of semantic tokens."""
        parts = [
            entry.category,
            entry.category,
            entry.category,
            entry.definition,
            entry.definition,
            " ".join(entry.synonyms),
            " ".join(entry.synonyms),
            " ".join(entry.related),
        ]
        return tokenize(" ".join(parts))

    def _vector(self, document: Iterable[str]) -> dict[str, float]:
        counts = Counter(document)
        vector = {
            token: (1.0 + math.log(count)) * self._idf.get(token, 1.0)
            for token, count in counts.items()
        }
        norm = math.sqrt(sum(value * value for value in vector.values()))
        if norm == 0.0:
            return {}
        return {token: value / norm for token, value in vector.items()}

    @staticmethod
    def _cosine(
        left: Mapping[str, float], right: Mapping[str, float]
    ) -> float:
        if len(left) > len(right):
            left, right = right, left
        dot = sum(value * right.get(token, 0.0) for token, value in left.items())
        if dot <= 0.0:
            return 0.0
        return max(0.0, min(1.0, dot))

    def vector_for(self, entry: WordEntry) -> Mapping[str, float]:
        return self._vector_by_id.get(entry.id, {})

    def score(
        self,
        target: WordEntry,
        guess: str,
        repository: WordRepository,
    ) -> ScoreResult:
        """Score ``guess`` against ``target`` on a 0-100 scale."""
        key = _normalise_term(guess)
        if not key:
            return ScoreResult(0.0, 0.0, known=False, correct=False)

        target_synonyms = {synonym.casefold() for synonym in target.synonyms}
        if key == target.word.casefold() or key in target_synonyms:
            return ScoreResult(1.0, 100.0, known=True, correct=True,
                               matched_word=target.word)

        candidates = repository.candidates(guess)
        if not candidates:
            return ScoreResult(0.0, 0.0, known=False, correct=False)

        target_vector = self.vector_for(target)
        best_entry: WordEntry | None = None
        best_cosine = 0.0
        for candidate in candidates:
            similarity = self._cosine(target_vector, self.vector_for(candidate))
            if best_entry is None or similarity > best_cosine:
                best_entry, best_cosine = candidate, similarity

        # A generated entry can be nearly identical to another entry (for
        # example, two senses with the same gloss).  Only an exact answer or a
        # listed synonym earns a perfect 100.
        points = round(best_cosine * 100.0, 1)
        if points >= 100.0:
            points = 99.9
        return ScoreResult(
            cosine=best_cosine,
            points=points,
            known=True,
            correct=False,
            matched_word=best_entry.word if best_entry else None,
        )

    def similarity(self, left: WordEntry, right: WordEntry) -> float:
        """Return the cosine similarity between two database entries."""
        return self._cosine(self.vector_for(left), self.vector_for(right))

    def nearest(
        self, entry: WordEntry, limit: int = 5
    ) -> tuple[tuple[WordEntry, float], ...]:
        """Return the most semantically similar database entries."""
        scored = [
            (other, self.similarity(entry, other))
            for other in self._entries
            if other.id != entry.id
        ]
        scored.sort(key=lambda pair: pair[1], reverse=True)
        return tuple(scored[:limit])
