{"content": """"Round and session state for the word-guessing game."""

from __future__ import annotations

import random
from dataclasses import dataclass, field

from .database import WordEntry, WordRepository
from .description import describe, hint as make_hint
from .similarity import ScoreResult, SemanticScorer


def score_label(points: float) -> str:
    if points >= 100.0:
        return "PERFECT"
    if points >= 90.0:
        return "Blazing hot"
    if points >= 70.0:
        return "Hot"
    if points >= 45.0:
        return "Warm"
    if points >= 20.0:
        return "Cool"
    if points > 0.0:
        return "Cold"
    return "Freezing"


@dataclass(slots=True)
class GuessOutcome:
    guess: str
    result: ScoreResult
    number: int
    duplicate: bool = False
    new_best: bool = False

    @property
    def points(self) -> float:
        return self.result.points

    @property
    def label(self) -> str:
        return score_label(self.points)


@dataclass(slots=True)
class Round:
    """One secret word, its clue, and the guesses made against it."""

    target: WordEntry
    scorer: SemanticScorer
    repository: WordRepository
    max_guesses: int = 6
    description: str = field(init=False)
    outcomes: list[GuessOutcome] = field(default_factory=list)
    hints_used: int = 0
    finished: bool = False
    won: bool = False
    gave_up: bool = False

    def __post_init__(self) -> None:
        if self.max_guesses < 1:
            raise ValueError("max_guesses must be at least 1")
        self.description = describe(self.target)
        self._seen: set[str] = set()

    @property
    def guesses_used(self) -> int:
        return len(self.outcomes)

    @property
    def guesses_left(self) -> int:
        return max(0, self.max_guesses - self.guesses_used)

    @property
    def best(self) -> GuessOutcome | None:
        real = [outcome for outcome in self.outcomes if not outcome.duplicate]
        if not real:
            return None
        return max(real, key=lambda outcome: outcome.points)

    def guess(self, word: str) -> GuessOutcome:
        if self.finished:
            raise RuntimeError("This round is already over")
        cleaned = " ".join(word.strip().split())
        key = cleaned.casefold()
        if not key:
            raise ValueError("Guess cannot be empty")
        if key in self._seen:
            return GuessOutcome(
                guess=cleaned,
                result=ScoreResult(0.0, 0.0, known=False, correct=False),
                number=self.guesses_used,
                duplicate=True,
            )
        self._seen.add(key)

        previous_best = self.best.points if self.best else -1.0
        result = self.scorer.score(self.target, cleaned, self.repository)
        outcome = GuessOutcome(
            guess=cleaned,
            result=result,
            number=self.guesses_used + 1,
            new_best=result.points > previous_best,
        )
        self.outcomes.append(outcome)

        if result.correct:
            self.finished = True
            self.won = True
        elif self.guesses_used >= self.max_guesses:
            self.finished = True
        return outcome

    def use_hint(self) -> str | None:
        if self.finished or self.hints_used >= 1:
            return None
        self.hints_used += 1
        return make_hint(self.target, self.hints_used - 1)

    def give_up(self) -> None:
        self.finished = True
        self.gave_up = True
        self.won = False

    @property
    def result_line(self) -> str:
