    """Reject obvious plurals, past tenses, and abbreviations."""
    if word in ABBREVIATIONS:
        return True
    if word in PLURAL_EXCEPTIONS:
        return False
    if word in IRREGULAR_VERB_FORMS and pos != "n":
        return True
