            return True
        if word.endswith("es") and (
            word[:-2] in frequency or word[:-1] in frequency
        ):
            return True
        if word[:-1] in frequency:
            return True
    return False


def _select_words(candidates: list[dict], limit: int) -> list[dict]:
    """Pick a balanced subset across categories and difficulty levels."""
    by_category: dict[str, list[dict]] = defaultdict(list)
    for candidate in candidates:
        by_category[candidate["category"]].append(candidate)

    selected: list[dict] = []
    used_synsets: set[tuple[str, str]] = set()

    def usable(pool: list[dict]) -> list[dict]:
        return [
            candidate
            for candidate in pool
            if candidate["_synset_key"] not in used_synsets
        ]

    for category, target in CATEGORY_TARGETS.items():
        pool = sorted(
            usable(by_category.get(category, [])),
            key=lambda item: item["frequency_rank"],
        )
        if not pool or target <= 0:
            continue
        picked: list[dict] = []
        if target < 5:
            picked = pool[:target]
        else:
            buckets = {
                difficulty: [
                    candidate
                    for candidate in pool
                    if candidate["difficulty"] == difficulty
                ]
                for difficulty in ("easy", "medium", "hard")
            }
            quotas = {
                "easy": round(target * 0.30),
                "medium": round(target * 0.40),
                "hard": round(target * 0.30),
            }
            for difficulty in ("easy", "medium", "hard"):
                for candidate in buckets[difficulty][: quotas[difficulty]]:
                    if len(picked) >= target:
                        break
                    if candidate["_synset_key"] in used_synsets:
                        continue
                    picked.append(candidate)
            if len(picked) < target:
                chosen_ids = {id(candidate) for candidate in picked}
                for candidate in pool:
                    if len(picked) >= target:
                        break
                    if id(candidate) in chosen_ids:
                        continue
                    if candidate["_synset_key"] in used_synsets:
                        continue
                    picked.append(candidate)

        for candidate in picked:
            key = candidate["_synset_key"]
            if key in used_synsets:
                continue
            used_synsets.add(key)
            selected.append(candidate)

    if len(selected) < limit:
        for candidate in sorted(
            candidates, key=lambda item: item["frequency_rank"]
        ):
            if len(selected) >= limit:
                break
            key = candidate["_synset_key"]
            if key in used_synsets:
                continue
            used_synsets.add(key)
            selected.append(candidate)

    selected.sort(key=lambda item: item["frequency_rank"])
    for item in selected:
        item.pop("_synset_key", None)
    return selected


