{"content": """"Command-line interface for Word Sleuth."""

from __future__ import annotations

import argparse
import os
import random
import shutil
import sys
from pathlib import Path

from . import __version__
from .database import DEFAULT_DB_PATH, WordRepository
from .game import Round, SessionStats, new_round, score_label
from .similarity import SemanticScorer

RESET = "\033[0m"
BOLD = "\033[1m"
DIM = "\033[2m"
CYAN = "\033[36m"
GREEN = "\033[32m"
YELLOW = "\033[33m"
RED = "\033[31m"


class Palette:
    """Tiny ANSI helper that respects NO_COLOR and non-TTY output."""

    def __init__(self, enabled: bool) -> None:
        self.enabled = enabled

    def paint(self, text: str, *codes: str) -> str:
        if not self.enabled or not codes:
            return text
        return "".join(codes) + text + RESET

    def bold(self, text: str) -> str:
        return self.paint(text, BOLD)

    def dim(self, text: str) -> str:
        return self.paint(text, DIM)

    def cyan(self, text: str) -> str:
        return self.paint(text, CYAN)

    def green(self, text: str) -> str:
        return self.paint(text, GREEN)

    def yellow(self, text: str) -> str:
        return self.paint(text, YELLOW)

    def red(self, text: str) -> str:
        return self.paint(text, RED)


def _positive_int(value: str) -> int:
    try:
        number = int(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError("must be an integer") from exc
    if number < 1:
        raise argparse.ArgumentTypeError("must be at least 1")
    return number


def _score_color(points: float) -> str:
    if points >= 70:
        return GREEN
    if points >= 40:
        return YELLOW
    return RED


def _score_bar(points: float, width: int = 18) -> str:
    filled = max(0, min(width, round(points / 100.0 * width)))
    return "#" * filled + "-" * (width - filled)


class Console:
    def __init__(self, palette: Palette) -> None:
        self.palette = palette

    def line(self, text: str = "") -> None:
        print(text)

    def rule(self) -> None:
        width = max(52, min(78, shutil.get_terminal_size((80, 24)).columns))
        self.line(self.palette.dim("-" * width))

    def banner(self) -> None:
        self.line()
        self.line(self.palette.bold(self.palette.cyan("  WORD SLEUTH")))
        self.line(self.palette.dim("  a semantic word-guessing game"))
        self.rule()

    def clue(self, round_: Round, category: str | None, difficulty: str | None) -> None:
        self.line()
        self.line(self.palette.bold("  I picked a secret word."))
        labels = []
        if category:
            labels.append(f"category: {category}")
        if difficulty:
            labels.append(f"difficulty: {difficulty}")
        if labels:
            self.line("  Filters: " + " | ".join(labels))
        self.line()
        for line in round_.description.splitlines():
            self.line("  " + line)
        self.line()
        self.line(
            f"  You have {round_.max_guesses} guesses. "
            "Type a word, 'hint', 'skip', or 'quit'."
        )
        self.line(
            self.palette.dim(
                "  Scores are cosine similarity (0-100) against the clue's "
                "semantic vector."
            )
        )
        self.line()

    def outcome(self, round_: Round, outcome) -> None:
        if outcome.duplicate:
            self.line(
                self.palette.yellow(
                    f"  You already tried '{outcome.guess}'. Guess again."
                )
            )
            return

        points = outcome.points
        color = _score_color(points)
        bar = self.palette.paint(_score_bar(points), color)
        score = self.palette.paint(f"{points:5.1f}/100", color)
        label = self.palette.paint(outcome.label, color)
        name = outcome.guess.upper()
        suffix = ""
        if outcome.new_best and outcome.number > 1 and not outcome.result.correct:
            suffix = self.palette.dim("  new best")
        self.line(f"  {name:<16} [{bar}] {score}  {label}{suffix}")

        if outcome.result.correct:
            if outcome.result.matched_word and outcome.guess.casefold() != (
                round_.target.word.casefold()
            ):
                self.line(
                    self.palette.green(
                        f"  That is a synonym of the answer, "
                        f"{round_.target.word.upper()}!"
                    )
                )
            else:
                self.line(self.palette.green("  Correct!"))
            return

        if not outcome.result.known:
            self.line(
                self.palette.dim(
                    "  That word is not in my vocabulary, so it has no "
                    "semantic vector. Try a common synonym."
                )
            )
            suggestions = round_.repository.suggest(outcome.guess)
            if suggestions:
                self.line(
                    self.palette.dim(
                        "  Did you mean: " + ", ".join(suggestions) + "?"
                    )
                )
        elif points >= 70:
            self.line(self.palette.yellow("  You are close."))

    def hint(self, message: str) -> None:
        self.line(self.palette.cyan("  Hint: " + message))

    def help(self) -> None:
        self.line()
        self.line(self.palette.bold("  Commands"))
        self.line("    hint   reveal the first letter (once per round)")
        self.line("    skip   give up and see the answer")
        self.line("    quit   leave the game")
        self.line("    help   show this list")
        self.line()

    def reveal(self, round_: Round) -> None:
        self.line()
        self.rule()
        self.line("  " + self.palette.bold(round_.result_line))
        if round_.best is not None:
            best = round_.best
            self.line(
                f"  Best guess: {best.guess.upper()} "
                f"({best.points:.1f}/100, {best.label})"
            )
        self.line("  Definition: " + round_.target.definition)
        if round_.target.synonyms:
            self.line("  Synonyms: " + round_.target.synonyms_text)
        self.line(
            self.palette.dim(
                f"  Category: {round_.target.category} | "
                f"Difficulty: {round_.target.difficulty} | "
                f"Letters: {round_.target.letter_count}"
            )
        )
        self.line()


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="word_guessing.py",
        description="Guess a secret word from its definition. "
        "Each guess is scored with cosine similarity.",
    )
    parser.add_argument(
        "--word",
        help="play with a specific secret word (for testing or practice)",
    )
    parser.add_argument(
        "--seed",
        type=int,
        help="seed the random word choice for reproducible rounds",
    )
    parser.add_argument(
        "--guesses",
        type=_positive_int,
        default=6,
        help="maximum guesses per round (default: 6)",
    )
    parser.add_argument(
        "--category",
        help="only choose words from this category",
    )
    parser.add_argument(
        "--difficulty",
        choices=("easy", "medium", "hard"),
        help="only choose words of this difficulty",
    )
    parser.add_argument(
        "--db",
        type=Path,
        help=f"path to the SQLite database (default: {DEFAULT_DB_PATH})",
    )
    parser.add_argument(
        "--no-color",
        action="store_true",
        help="disable ANSI colors",
    )
    parser.add_argument(
        "--list-categories",
        action="store_true",
        help="show database categories and exit",
    )
    parser.add_argument(
        "--stats",
        action="store_true",
        help="show database statistics and exit",
    )
    parser.add_argument(
        "--version",
        action="version",
        version=f"%(prog)s {__version__}",
    )
    return parser


def _palette(args: argparse.Namespace) -> Palette:
    enabled = (
        not args.no_color
        and sys.stdout.isatty()
        and not os.environ.get("NO_COLOR")
        and os.environ.get("TERM") != "dumb"
    )
    if enabled and os.name == "nt":
        # Ask modern Windows terminals to interpret ANSI escapes.
        os.system("")
    return Palette(enabled)


def _print_stats(repository: WordRepository, console: Console) -> None:
    from collections import Counter

    categories = Counter(entry.category for entry in repository.entries)
    difficulties = Counter(entry.difficulty for entry in repository.entries)
    console.line()
    console.line(console.palette.bold("  Word Sleuth database"))
    console.line(f"  Path: {repository.db_path}")
    console.line(f"  Words: {len(repository):,}")
    console.line(
        "  Difficulty: "
        + ", ".join(f"{key} {difficulties[key]}" for key in sorted(difficulties))
    )
    console.line("  Categories:")
    for name, count in categories.most_common():
        console.line(f"    {name:<20} {count:>4}")
    console.line()


def _validate_filters(
    repository: WordRepository, args: argparse.Namespace, parser: argparse.ArgumentParser
) -> tuple[str | None, str | None]:
    category = args.category
    if category:
        match = next(
            (item for item in repository.categories() if item.casefold() == category.casefold()),
            None,
        )
        if match is None:
            parser.error(
                f"unknown category {category!r}; choose one of: "
                + ", ".join(repository.categories())
            )
        category = match
    difficulty = args.difficulty.casefold() if args.difficulty else None
    if difficulty and difficulty not in repository.difficulties():
        parser.error(
            f"unknown difficulty {difficulty!r}; choose one of: "
            + ", ".join(repository.difficulties())
        )
    return category, difficulty


def _play_round(
    round_: Round,
    console: Console,
    category: str | None,
    difficulty: str | None,
) -> str:
    """Play one round. Returns 'finished', 'quit', or 'eof'."""
    console.clue(round_, category, difficulty)
    while not round_.finished:
        prompt = (
            f"  {console.palette.bold(f'Guess {round_.guesses_used + 1}/{round_.max_guesses}')}"
            " > "
        )
        try:
            raw = input(prompt)
        except EOFError:
            console.line()
            round_.give_up()
            console.line(console.palette.dim("  Input closed."))
            return "eof"
        except KeyboardInterrupt:
            console.line()
            round_.give_up()
            console.line(console.palette.dim("  Interrupted."))
            return "quit"

        command = raw.strip().casefold()
        if not command:
            continue
        if command in {"quit", "exit", "q"}:
            round_.give_up()
            console.line()
            return "quit"
        if command in {"skip", "pass"}:
            round_.give_up()
            break
        if command in {"help", "?"}:
            console.help()
            continue
        if command in {"hint", "h"}:
            message = round_.use_hint()
            if message is None:
                console.line(console.palette.dim("  You have already used your hint."))
            else:
                console.hint(message)
            continue

        try:
            outcome = round_.guess(raw)
        except ValueError as exc:
            console.line(console.palette.red(f"  {exc}"))
            continue
        console.outcome(round_, outcome)
        if round_.finished:
            break
        console.line()

    console.reveal(round_)
    return "finished"


def _play_again(console: Console) -> bool:
    try:
        answer = input("  Play again? [Y/n] > ").strip().casefold()
    except (EOFError, KeyboardInterrupt):
        console.line()
        return False
    return answer in {"", "y", "yes"}


def main(argv: list[str] | None = None) -> int:
    parser = _build_parser()
    args = parser.parse_args(argv)
    palette = _palette(args)
    console = Console(palette)

    try:
        repository = WordRepository(args.db)
    except Exception as exc:  # pragma: no cover - defensive CLI boundary
        print(f"Could not open the word database: {exc}", file=sys.stderr)
        return 2

    try:
        if args.stats:
            _print_stats(repository, console)
            return 0
        if args.list_categories:
            for category in repository.categories():
                count = sum(1 for e in repository.entries if e.category == category)
                console.line(f"{category} ({count})")
            return 0

        category, difficulty = _validate_filters(repository, args, parser)
        if args.word and (category or difficulty):
            parser.error("--word cannot be combined with --category or --difficulty")

        scorer = SemanticScorer(repository.entries)
        rng: random.Random = (
            random.Random(args.seed) if args.seed is not None else random.SystemRandom()
        )
        forced_target = None
        if args.word:
            forced_target = repository.get(args.word)
            if forced_target is None:
                suggestions = repository.suggest(args.word)
                hint_text = (
                    " Did you mean: " + ", ".join(suggestions) + "?"
                    if suggestions
                    else ""
                )
                parser.error(
                    f"word {args.word!r} is not in the database.{hint_text}"
                )

        console.banner()
        console.line(
            f"  {len(repository):,} common English words | "
            f"TF-IDF cosine scoring"
        )
        if args.seed is not None:
            console.line(console.palette.dim(f"  Random seed: {args.seed}"))
        console.line()

        stats = SessionStats()
        quit_requested = False
        while True:
            try:
                round_ = new_round(
                    repository,
                    scorer,
                    rng,
                    max_guesses=args.guesses,
                    category=category,
                    difficulty=difficulty,
                    target=forced_target,
                )
            except LookupError as exc:
                parser.error(str(exc))
                return 2

            result = _play_round(round_, console, category, difficulty)
            if not round_.gave_up and not round_.finished:
                round_.give_up()
            stats.record(round_)
            if result in {"quit", "eof"}:
                quit_requested = True
            if quit_requested or not _play_again(console):
                break
            console.line()

        if stats.rounds:
            console.line(console.palette.dim("  " + stats.summary()))
            console.line()
        return 0
    finally:
        repository.close()


if __name__ == "__main__":  # pragma: no cover
    raise SystemExit(main())
