def ordered_synsets(
    word: str,
    indexes: dict[tuple[str, str], tuple[str, ...]],
    synsets: dict[tuple[str, str], Synset],
    sense_counts: Counter[tuple[str, str]],
) -> list[Synset]:
    """Return a word's senses, best POS first, then in WordNet sense order."""
    pos_groups: list[tuple[int, int, str, tuple[str, ...]]] = []
    for pos in ("n", "v", "a", "r"):
        offsets = indexes.get((word, pos))
        if not offsets:
            continue
        pos_groups.append(
            (sense_counts.get((word, pos), 0), POS_PRIORITY[pos], pos, offsets)
        )
    pos_groups.sort(key=lambda item: (-item[0], item[1]))

    options: list[Synset] = []
    seen: set[tuple[str, str]] = set()
    for _, _, pos, offsets in pos_groups:
        for offset in offsets:
            synset = synsets.get((pos, offset))
            if synset is None:
                continue
            key = (POS_GROUP.get(synset.pos, synset.pos), synset.offset)
            if key in seen:
                continue
            seen.add(key)
            options.append(synset)
    return options


