{"content": """"Clue and hint generation."""

from __future__ import annotations

import re

from .database import WordEntry


def _secret_terms(entry: WordEntry) -> tuple[str, ...]:
    """The answer plus synonyms that should never appear in a clue."""
    terms: list[str] = []
    for term in (entry.word, *entry.synonyms):
        cleaned = " ".join(term.strip().split())
        if cleaned and cleaned.casefold() not in {t.casefold() for t in terms}:
            terms.append(cleaned)
    # Longest first so multi-word synonyms are masked before their parts.
    return tuple(sorted(terms, key=len, reverse=True))


def _secret_pattern(term: str) -> re.Pattern[str]:
    return re.compile(
        r"(?<![A-Za-z])"
        + re.escape(term)
        + r"(?:'s|s|es|ed|ing|ning)?(?![A-Za-z])",
        re.IGNORECASE,
    )


def _mask_terms(text: str, entry: WordEntry) -> str:
    """Mask the answer and its listed synonyms inside a clue fragment."""
    for term in _secret_terms(entry):
        text = _secret_pattern(term).sub("_____", text)
    return text


def _contains_secret(text: str, entry: WordEntry) -> bool:
    return any(
        _secret_pattern(term).search(text) for term in _secret_terms(entry)
    )


def _finish_sentence(text: str) -> str:
    text = " ".join(text.strip().split())
    text = text.rstrip(" ;,")
    if text and text[0].islower():
        text = text[0].upper() + text[1:]
    if text and text[-1] not in ".!?":
        text += "."
    return text


def _context_terms(entry: WordEntry, limit: int = 4) -> tuple[str, ...]:
    """Safe related concepts for nouns and verbs.

    Adjective/adverb relations are usually close synonyms, so they are omitted;
    an example sentence is a better context source for those.
    """
    if entry.pos not in ("n", "v"):
        return ()
    terms: list[str] = []
    for related in entry.related:
        cleaned = " ".join(related.strip().split())
        if not cleaned or cleaned.casefold() in {
            term.casefold() for term in _secret_terms(entry)
        }:
            continue
        if _contains_secret(cleaned, entry):
            continue
        if cleaned.casefold() in {term.casefold() for term in terms}:
            continue
        terms.append(cleaned)
        if len(terms) >= limit:
            break
    return tuple(terms)


def describe(entry: WordEntry, include_category: bool = True) -> str:
    """Generate a longer, contextual description without revealing the word."""
    if include_category and entry.pos not in ("a", "s", "r"):
        intro = (
            f"It is a {entry.letter_count}-letter {entry.display_pos} "
            f"in the {entry.category} category."
        )
    else:
        intro = f"It is a {entry.letter_count}-letter {entry.display_pos}."

    lines = [intro, ""]
    definition = _finish_sentence(_mask_terms(entry.definition, entry))
    lines.append("Definition: " + definition)

    if entry.example:
        example = _finish_sentence(_mask_terms(entry.example, entry))
        lines.extend(["", "Example: " + f'"{example}"'])

    context = _context_terms(entry)
    if context:
        lines.extend(["", "Related ideas: " + ", ".join(context)])

    return "\n".join(lines).rstrip()


def hint(entry: WordEntry, hints_used: int = 0) -> str:
    """Return a one-time hint that reveals the first letter."""
    letters = [ch for ch in entry.word if ch.isalpha()]
    first = letters[0].upper() if letters else "?"
    if hints_used <= 0:
        return f"The first letter is '{first}'."
    return "You have used your hint for this round."


def first_letter_word(entry: WordEntry) -> str:
    for ch in entry.word:
        if ch.isalpha():
            return ch.upper()
    return "?"
